import base64
import pathlib

LOGO_BASE64 = """"""

def ensure_watermark():
    candidates = [
        pathlib.Path("/assets/lunartech-logo.png"),
        pathlib.Path(__file__).parent.resolve() / "assets" / "lunartech-logo.png",
    ]
    for target in candidates:
        if not target.exists():
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(base64.b64decode(LOGO_BASE64))
            except Exception:
                pass
    for target in candidates:
        if target.exists():
            return str(target)
    return str(candidates[1])
